export function effectiveStoryEdges(graph,node){const patch=graph.edits?.commands?.[node.at];return(node.edges||[]).map(e=>{if(e.standardArg!==undefined&&patch){const to=graph.adapter?.standardEntries?.[patch.args[e.standardArg]];return{...e,to:to??e.to};}const i=node.args?.findIndex(a=>a.at===e.field);return i>=0&&patch?{...e,to:patch.args[i]-BASE,kind:[6,7].includes(node.code)?'condition '+patch.args[0]:e.kind}:e;});}
export function reachableStory(graph,address,limit=180000){const seen=new Set(),queue=[address];while(queue.length&&seen.size<limit){const at=queue.shift();if(seen.has(at)||!graph.nodes[at])continue;seen.add(at);queue.push(...effectiveStoryEdges(graph,graph.nodes[at]).map(e=>e.to));}return seen;}
export function nativeStoryEditCount(project,sourceId){const e=project.nativeStory?.[sourceId]?.edits;return e?Object.values(e).reduce((n,rows)=>n+Object.keys(rows||{}).length,0):0;}
export function encodeStoryText(text){if(typeof text!=='string')throw Error('Dialogue must be text.');return encodeScriptText(text.replace(/(?<!\\)\$/g,'\\$').replace(/\r?\n/g,'\\n'));}
export function parseStoryNumber(text,width){const s=String(text).trim();if(!/^(0x[0-9a-f]+|\d+)$/i.test(s))throw Error('Enter a decimal number or 0x hexadecimal value.');const n=Number(s);if(!Number.isSafeInteger(n)||n<0||n>2**(width*8)-1)throw Error('The value does not fit this command field.');return n;}
export function movementNames(){return Object.entries(SCRIPT_DATA.movements).map(([name,code])=>({name,code}));}
