 assertStoryFlowBindings(saved,graph);const changed=new Set([...Object.keys(e.commands||{}).map(Number),...Object.values(e.flows||{}).map(f=>f.address)]),pointerOwners=new Map();for(const n of Object.values(graph.nodes))for(const a of n.args||[])pointerOwners.set(a.at,n.at);for(const kind of['texts','movements'])for(const key of Object.keys(e[kind]||{}))for(const ref of graph[kind][key]?.references||[]){const owner=pointerOwners.get(ref);if(owner!==undefined)changed.add(owner);}const incoming=new Map();for(const n of Object.values(graph.nodes))for(const edge of n.edges||[]){if(!incoming.has(edge.to))incoming.set(edge.to,[]);incoming.get(edge.to).push(n.at);}const affected=new Set(),work=[...changed];while(work.length){const at=work.shift();if(affected.has(at))continue;affected.add(at);work.push(...incoming.get(at)||[]);}for(const root of graph.roots){if(!affected.has(root.address)||!['npcs','signs','triggers'].includes(root.kind))continue;const type={npcs:'npc',signs:'sign',triggers:'trigger'}[root.kind],map=project.maps?.find(m=>!m.rom?.isCopy&&m.rom?.sourceId===sourceId&&m.rom.key===root.mapKey),marker=map?.markers.find(n=>n.rom?.type===type&&n.rom.index===root.index);if(marker?.runtime&&marker.runtime.enabled!==false)throw Error('This event also has an authored replacement scene. Keep one source of event edits: '+map.name+' / '+marker.title);}
