export function validateNativeStory(project){if(project.nativeStory===undefined)return;if(!project.nativeStory||typeof project.nativeStory!=='object'||Array.isArray(project.nativeStory)||JSON.stringify(project.nativeStory).length>60e6)throw Error('Invalid native story data.');for(const g of Object.values(project.nativeStory)){if(g?.version!==1||!['frlg','rse'].includes(g.engine)||!Number.isInteger(g.sourceSize)||g.sourceSize<512||g.sourceSize>33554432||!Array.isArray(g.roots)||g.roots.length>100000||!Array.isArray(g.mapKeys)||!Array.isArray(g.notices)||!g.nodes||!g.texts||!g.movements||!g.edits||Object.keys(g.nodes).length>180000)throw Error('Invalid native story graph.');for(const key of['commands','texts','movements','conditions','nativeData','flows'])if(g.edits[key]!==undefined&&(!g.edits[key]||typeof g.edits[key]!=='object'||Array.isArray(g.edits[key])))throw Error('Invalid native story edits.');for(const r of g.roots)if(!r||typeof r.id!=='string'||typeof r.mapKey!=='string'||typeof r.title!=='string'||!Number.isInteger(r.address)||r.address<512||r.address>=g.sourceSize)throw Error('Invalid native story entry.');for(const n of Object.values(g.nodes))if(!n||!Number.isInteger(n.at)||n.at<512||n.at>=g.sourceSize||typeof n.name!=='string'||!Array.isArray(n.edges)||!n.opaque&&(!Array.isArray(n.args)||typeof n.original!=='string'))throw Error('Invalid native story command.');assertStoryFlowBindings(g,g);}}

export async function refreshNativeStory(previous,reader){if(previous.engine!==reader.engine||previous.mapKeys.some(k=>!reader.byKey(k)))throw Error('Native story map bindings changed; the original event graph and edits were retained.');const fresh=await indexNativeStory(reader,{mapKeys:previous.mapKeys,previous});for(const patch of Object.values(previous.edits.nativeData||{}))validateShatteredDataPatch(reader,patch);for(const[key,patch]of Object.entries(previous.edits.conditions||{}))if(!fresh.roots.some(r=>r.reference===Number(key)&&r.conditionOriginal===patch.original))throw Error('An authored map-entry condition changed; the original story edits were retained.');for(const kind of['commands','texts','movements'])for(const[key,patch]of Object.entries(previous.edits[kind]||{})){const row=(kind==='commands'?fresh.nodes:fresh[kind])[key];if(!row||row.opaque||row.original!==patch.original)throw Error('An authored native story '+kind+' entry moved or changed at '+Number(key).toString(16)+'. Keep the original ROM or resolve this story binding before refreshing.');}assertStoryFlowBindings(previous,fresh);return fresh;}
